def calculate_roth_ira_contribution(magi: float, filing_status: str, year: int) -> float:
    """
    Calculate the allowable Roth IRA contribution based on MAGI, filing status, and tax year.

    Args:
        magi (float): Modified Adjusted Gross Income.
        filing_status (str): Tax filing status ('single', 'married_jointly', 'married_separately').
        year (int): Tax year for which the contribution is calculated.

    Returns:
        contribution (float): The allowable contribution amount to a Roth IRA.

    Notes:
        - Applicability: Use this function for determining Roth IRA contributions under U.S. tax laws.
        - Constraints: Only applicable for years 2024 and 2025 with specific filing statuses.
        - Considerations: The contribution limits are subject to change; verify before use.
    """
    roth_limits = {
        2024: {
            'single': (146000, 161000),
            'married_jointly': (230000, 240000),
            'married_separately': (0, 10000)
        },
        2025: {
            'single': (150000, 165000),
            'married_jointly': (236000, 246000),
            'married_separately': (0, 10000)
        }
    }

    contribution_limits = {2024: 7000, 2025: 7000}

    phase_out_start, phase_out_end = roth_limits[year][filing_status]

    if magi < phase_out_start:
        return contribution_limits[year]
    elif magi >= phase_out_end:
        return 0
    else:
        range_span = phase_out_end - phase_out_start
        contribution_rate = (phase_out_end - magi) / range_span
        reduced_contribution = contribution_rate * contribution_limits[year]
        return max(0, min(reduced_contribution, contribution_limits[year]))

def calculate_gas_guzzler_tax(mpg: float) -> int:
    """
    Calculate the gas guzzler tax based on a vehicle's fuel efficiency.

    This function determines the amount of gas guzzler tax imposed on a passenger
    car based on its miles-per-gallon (mpg) fuel economy. The tax is part of a 
    U.S. government initiative to discourage low fuel economy vehicles.

    Args:
        mpg (float): The combined city and highway miles-per-gallon fuel efficiency
                     of the car.

    Returns:
        tax_amount (int): The calculated gas guzzler tax in dollars.

    Notes:
        - Applicability: This tax is applicable to passenger cars but not to 
          trucks, SUVs, or minivans.
        - Constraints: The function uses pre-defined tax brackets based on mpg 
          efficiency, ranging from $1,000 to $7,000.
        - Considerations: Tax brackets are defined for mpg values thresholds such as
          less than 12.5 mpg, less than 22.5 mpg, etc. Updates to the tax code could 
          change these brackets.
    """
    if mpg >= 22.5:
        return 0
    elif mpg < 12.5:
        return 7000
    elif mpg < 13.5:
        return 6400
    elif mpg < 14.5:
        return 5800
    elif mpg < 15.5:
        return 5000
    elif mpg < 16.5:
        return 4500
    elif mpg < 17.5:
        return 3800
    elif mpg < 18.5:
        return 3000
    elif mpg < 19.5:
        return 2600
    elif mpg < 20.5:
        return 2100
    elif mpg < 21.5:
        return 1600
    elif mpg < 22.5:
        return 1000
    else:
        return 0

def calculate_option_moneyness(underlying_price: float, strike_price: float, option_type: str) -> str:
    """
    Determine the moneyness of an option based on the strike price and market price of the underlying asset.

    This function calculates whether an option is in-the-money (ITM), out-of-the-money (OTM), or at-the-money (ATM)
    by comparing the strike price to the current market price of the underlying asset. 

    Args:
        underlying_price (float): The current market price of the underlying asset.
        strike_price (float): The strike price specified in the option contract.
        option_type (str): The type of option - "call" for call options or "put" for put options.

    Returns:
        moneyness (str): Returns "ITM" if the option is in-the-money, "OTM" if it is out-of-the-money, 
                         and "ATM" if it is at-the-money.

    Notes:
        - Applicability: This function is applicable for both call and put options.
        - Constraints: The option_type should be either "call" or "put". Invalid option_type will raise a ValueError.
        - Considerations: Ensure the underlying_price and strike_price are positive numbers.
    """
    if option_type not in ["call", "put"]:
        raise ValueError("option_type must be 'call' or 'put'.")

    if option_type == "call":
        if underlying_price > strike_price:
            return "ITM"
        elif underlying_price < strike_price:
            return "OTM"
        else:
            return "ATM"
    elif option_type == "put":
        if underlying_price < strike_price:
            return "ITM"
        elif underlying_price > strike_price:
            return "OTM"
        else:
            return "ATM"
